      if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) return;

      let timer: ReturnType<typeof setTimeout>;
      const tick = () => {
        timer = setTimeout(() => {
          heroFrame.value = (heroFrame.value + 1) % HEADLINE_FRAMES.length;
