  place-items: center;
  min-height: clamp(360px, 45vw, 560px);
  margin-bottom: clamp(32px, 5vw, 64px);
  padding: clamp(28px, 6vw, 80px);
  background: #17130f;
  color: #f7f0dd;
  text-align: center;
}

.landing-room-intro > img {
  position: absolute;
  inset: 0;
  z-index: -2;
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.landing-room-intro::before {
  content: "";
  position: absolute;
  inset: 0;
  z-index: -1;
  background: radial-gradient(ellipse at center, #0c0a08cc, #0c0a0833);
}

.landing-room-intro__copy {
  max-width: 32rem;
}

.landing-room-intro h2 {
  font-family: var(--font-display);
  font-size: clamp(1.8rem, 3.5vw, 2.8rem);
  line-height: 1.2;
}

.landing-room-intro p {
  margin-top: 1.25rem;
  font-family: var(--font-serif);
  font-size: 1.0625rem;
  line-height: 1.65;
}

.landing-room-intro a {
  display: inline-block;
  margin-top: 1.5rem;
  padding-block: 0.5rem;
  color: inherit;
  text-decoration: underline;
  text-underline-offset: 0.3em;
}

.landing-room-intro a:focus-visible {
  outline: 2px solid currentColor;
