  width: 100%;
  margin-inline: 0;
  min-height: 560px;
  color: var(--hero-ink);
}

.landing-closing-artwork::before {
  background: radial-gradient(ellipse at center, #0c0a08e6, #0c0a084d);
}

.landing-closing-artwork .landing-hero__photo {
  animation: none;
}

.landing-closing-artwork .landing-title {
  font-size: clamp(1.875rem, 4vw, 2.5rem);
}

.landing-closing-artwork p,
.landing-closing-artwork .landing-download-link {
  color: var(--hero-ink);
}

@media (max-width: 600px) {
  .landing-hero--garden .landing-hero__photo {
    object-fit: contain;
  }

  .landing-room-intro > img {
    object-position: 48% center;
  }
}

