const subjects=[["owl","A front-facing barn owl with a distinctive heart-shaped face","muted ochre"],["fox","A red fox in three-quarter portrait with clear pointed ears","muted vermilion"],["hare","A hare in three-quarter portrait with long upright ears","muted sage green"],["raven","A raven in side profile with a strong curved beak","muted slate blue"]];
await Promise.all(subjects.map(async ([name,subject,color])=>{
const prompt=`Use case: illustration-story. Create one square default profile avatar for Twyne, a literary writing desk. Subject: ${subject}. Sophisticated antique wood engraving with bold readable silhouette, warm ivory engraved linework and near-black ink shadows, against a flat ${color} background. Head and upper shoulders only, centrally composed with generous 15 percent safe margins for circular crop, recognizable at 32 pixels. Tactile printed ink, restrained detail, no distressed overlay obscuring the face. Cohesive collectible bookplate portrait, calm character, not cartoon mascot. No letters, text, frame, border, clothing, accessories, watermark, or multiple panels. Output one square image.`;
store(`avatar-prompt-${name}`,prompt);
const result=await tools.image_gen__imagegen({prompt,transparent_background:false});
store(`avatar-result-${name}`,result);generatedImage(result);
}));

